    // If a transport is already opened for this descriptor, reuse it.
    if (existing) {
      subscriber.next({ data });
      subscriber.complete();
      return;
    }

    let cancelled = false;
    open(data.descriptor)
      .then(transport => {
        if (cancelled) return;
        transports.set(data.descriptor, transport);
        subscriber.next({ data });
        subscriber.complete();
