Singleton from \"@ledgerhq/hw-transport-node-hid-singleton\";\nimport { open } from \"@ledgerhq/live-common/hw/index\";\nimport { DisconnectedDeviceDuringOperation, serializeError } from \"@ledgerhq/errors\";\nimport { MessagesMap } from \"./types\";\n\n// Opened transports, keyed by the device descriptor they were opened with.\nconst transports = new Map<string, Transport>();\n\n// Stop signals for the currently running `transportListen` streams, keyed by request id.\nconst listenStops = new Map<string, Subject<void>>();\n\n// Stop signals for the currently running `transportExchangeBulk` streams, keyed by request id.\nconst bulkStops = new Map<string, Subject<void>>();\n\nconst disconnectedError = (message: string) =>\n  serializeError(new DisconnectedDeviceDuringOperation(message));\n\n/**\n * Opens a transport for the given descriptor and stores it for later use.\n * Emits a response with the original `data` on success, and errors with a\n * `CantOpenDevice` error object if no registered transport module can open the\n * descriptor.\n */\nexport const transportOpen = ({ data }: MessagesMap[\"transport:open\"]) =>\n  new Observable(subscriber => {\n    const existing = transports.get(data.descriptor);\n    // If a transport is already opened for this descriptor, reuse it.\n    if (existing) {\n      subscriber.next({ data });\n      subscriber.complete();\n      return;\n    }\n\n    let cancelled = false;\n    open(data.descriptor)\n      .then(transport => {\n        if (cancelled) return;\n        transports.set(data.descriptor, transport);\n        subscriber.next({ data });\n        subscriber.complete();\n      })\n      .catch(error => {\n        if (cancelled) return;\n        subscriber.error(serializeError(error));\n      });\n\n    return () => {\n      cancelled = true;\n    };\n  });\n\n/**\n * Exchanges a single APDU with the opened transport. Emits the response buffer\n * as a hex string, and errors with a `DisconnectedDeviceDuringOperation` error\n * object when no transport is opened or the exchange fails.\n */\nexport const transportExchange = ({ data }: MessagesMap[\"transport:exchange\"]) =>\n  new Observable(subscriber => {\n    const transport = transports.get(data.descriptor);\n    if (!transport) {\n      subscriber.error(disconnectedError(\"No open transport for the given descriptor\"));\n      return;\n    }\n\n    let cancelled = false;\n    transport\n      .exchange(Buffer.from(data.apduHex, \"hex\"))\n      .then(response => {\n        if (cancelled) return;\n        subscriber.next({ data: response.toString(\"hex\") });\n        subscriber.complete();\n      })\n      .catch(error => {\n        if (cancelled) return;\n        subscriber.error(disconnectedError(error?.message ?? \"Exchange failed\"));\n      });\n\n    return () => {\n      cancelled = true;\n    };\n  });\n\n/**\n * Exchanges a list of APDUs with the opened transport, emitting one response per\n * APDU: `{ data }` on success and `{ error }` on failure. Errors once with a\n * `DisconnectedDeviceDuringOperation` error object when no transport is opened.\n */\nexport const transportExchangeBulk = ({\n  data,\n  requestId,\n}: MessagesMap[\"transport:exchangeBulk\"]) =>\n  new Observable(subscriber => {\n    const transport = transports.get(data.descriptor);\n    if (!transport) {\n      subscriber.error(disconnectedError(\"No open transport for the given descriptor\"));\n      return;\n    }\n\n    let stopped = false;\n    const stop$ = new Subject<void>();\n    const stopSub = stop$.subscribe(() => {\n      stopped = true;\n    });\n    bulkStops.set(requestId, stop$);\n\n    const cleanup = () => {\n      stopSub.unsubscribe();\n      bulkStops.delete(requestId);\n    };\n\n    (async () => {\n      for (const apduHex of data.apdusHex) {\n        if (stopped) break;\n        try {\n          const response = await transport.exchange(Buffer.from(apduHex, \"hex\"));\n          if (stopped) break;\n          subscriber.next({ data: response.toString(\"hex\") });\n        } catch (error) {\n          if (stopped) break;\n          subscriber.next({\n            error: {\n              name: \"DisconnectedDeviceDuringOperation\",\n              message: (error as Error)?.message ?? \"Exchange failed\",\n            },\n          });\n        }\n      }\n      if (!stopped) subscriber.complete();\n      cleanup();\n    })();\n\n    return () => {\n      stopped = true;\n      cleanup();\n    };\n  });\n\n/**\n * Stops the `transportExchangeBulk` stream associated with the given request id.\n * Completes immediately without emitting.\n */\nexport const transportExchangeBulkUnsubscribe = ({\n  requestId,\n}: MessagesMap[\"transport:exchangeBulk:unsubscribe\"]) => {\n  const stop$ = bulkStops.get(requestId);\n  if (stop$) {\n    stop$.next();\n    stop$.complete();\n    bulkStops.delete(requestId);\n  }\n  return EMPTY;\n};\n\n/**\n * Listens to USB/HID device events and emits `{ data: { type, descriptor } }`\n * for each of them. The stream can be stopped through `transportListenUnsubscribe`.\n */\nexport const transportListen = ({ requestId }: MessagesMap[\"transport:listen\"]) => {\n  const stop$ = new Subject<void>();\n  listenStops.set(requestId, stop$);\n\n  return new Observable<{ data: { type: \"add\" | \"remove\"; descriptor: string } }>(subscriber => {\n    const subscription = TransportNodeHidSingleton.listen({\n      next: event =>\n        subscriber.next({\n          data: { type: event.type, descriptor: event.descriptor },\n        }),\n      error: error => subscriber.error(serializeError(error)),\n      complete: () => subscriber.complete(),\n    });\n\n    return () => {\n      subscription.unsubscribe();\n      listenStops.delete(requestId);\n    };\n  }).pipe(takeUntil(stop$));\n};\n\n/**\n * Stops the `transportListen` stream associated with the given request id. The\n * returned Observable completes immediately without emitting, while the matching\n * `transportListen` Observable completes and stops emitting events.\n */\nexport const transportListenUnsubscribe = ({\n  requestId,\n}: MessagesMap[\"transport:listen:unsubscribe\"]) => {\n  const stop$ = listenStops.get(requestId);\n  if (stop$) {\n    stop$.next();\n    stop$.complete();\n    listenStops.delete(requestId);\n  }\n  return EMPTY;\n};\n\n/**\n * Closes the transport opened for the given descriptor, removing it from the\n * internal store. Emits `{ type: \"ok\", data }` on success and errors with a\n * `DisconnectedDeviceDuringOperation` error object when no transport is opened.\n */\nexport const transportClose = ({ data }: MessagesMap[\"transport:close\"]) =>\n  new Observable(subscriber => {\n    const transport = transports.get(data.descriptor);\n    if (!transport) {\n      subscriber.error(disconnectedError(\"No open transport for the given descriptor\"));\n      return;\n    }\n\n    let cancelled = false;\n    Promise.resolve(transport.close())\n      .then(() => {\n        transports.delete(data.descriptor);\n        if (cancelled) return;\n        subscriber.next({ type: \"ok\", data });\n        subscriber.complete();\n      })\n      .catch(error => {\n        transports.delete(data.descriptor);\n        if (cancelled) return;\n        subscriber.error(disconnectedError(error?.message ?? \"Close failed\"));\n      });\n\n    return () => {\n      cancelled = true;\n    };\n  });\n"],"version":3}
