    );\n    expect(results).toEqual([\n      { data: \"aa\" },\n      { error: { name: \"DisconnectedDeviceDuringOperation\", message: \"boom\" } },\n      { data: \"bb\" },\n    ]);\n  });\n\n  it(\"listen maps events and unsubscribe completes it\", async () => {\n    let observer: any;\n    const unsubscribe = jest.fn();\n    listenMock.mockImplementation((o: any) => {\n      observer = o;\n      return { unsubscribe };\n    });\n    const events: any[] = [];\n    let completed = false;\n    const sub = transportListen({ requestId: \"rl\" }).subscribe({\n      next: e => events.push(e),\n      complete: () => {\n        completed = true;\n      },\n    });\n    observer.next({ type: \"add\", descriptor: \"usb1\" });\n    expect(events).toEqual([{ data: { type: \"add\", descriptor: \"usb1\" } }]);\n\n    const unsub = transportListenUnsubscribe({ data: { descriptor: \"\" }, requestId: \"rl\" } as any);\n    const wasEmpty = await firstValueFrom(unsub.pipe(isEmpty()) as any);\n    expect(wasEmpty).toBe(true);\n    expect(completed).toBe(true);\n    sub.unsubscribe();\n  });\n\n  it(\"close calls transport.close and emits ok\", async () => {\n    const t = fakeTransport();\n    openMock.mockResolvedValue(t);\n    await firstValueFrom(transportOpen({ data: { descriptor: \"c\" }, requestId: \"r\" }) as any);\n    const res = await firstValueFrom(transportClose({ data: { descriptor: \"c\" }, requestId: \"r\" }) as any);\n    expect(t.close).toHaveBeenCalled();\n    expect(res).toEqual({ type: \"ok\", data: { descriptor: \"c\" } });\n    // now closed -> error\n    await expect(\n      firstValueFrom(transportClose({ data: { descriptor: \"c\" }, requestId: \"r\" }) as any),\n    ).rejects.toMatchObject({ name: \"DisconnectedDeviceDuringOperation\" });\n  });\n});\n"],"version":3}
